-- 客服工作台 migration（schema + RLS + 种子，幂等）—— gen_seed.js 生成

CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) UNIQUE, password_hash VARCHAR(255), nick VARCHAR(120), role VARCHAR(30) DEFAULT 'member', status VARCHAR(20) DEFAULT 'approved', permissions TEXT DEFAULT '[]', last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS seed_meta (k VARCHAR(80) PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS tickets (id BIGSERIAL PRIMARY KEY, ticket_no VARCHAR(60) UNIQUE, customer_id INT, customer_name VARCHAR(120), region VARCHAR(60), channel VARCHAR(30), biz_type VARCHAR(10), cat_path VARCHAR(300), cat_code VARCHAR(40), shelf_id VARCHAR(60), shelf_code VARCHAR(60), risk VARCHAR(30), urgency VARCHAR(20), escalate BOOLEAN DEFAULT false, role VARCHAR(30), demand TEXT, content TEXT, visible_content TEXT, status VARCHAR(20) DEFAULT '待受理', handler VARCHAR(80), creator VARCHAR(80), sla_hours NUMERIC DEFAULT 24, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS ticket_events (id BIGSERIAL PRIMARY KEY, ticket_id INT, actor VARCHAR(80), action VARCHAR(60), detail TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS closures (id BIGSERIAL PRIMARY KEY, ticket_id INT, product_codes VARCHAR(200), product_name VARCHAR(200), problem VARCHAR(60), visible_issue BOOLEAN, prod_date VARCHAR(20), decider VARCHAR(60), refund_flag VARCHAR(20), refuse_claim BOOLEAN, demand_amount NUMERIC(10,2), refund_amount NUMERIC(10,2), pay_amount NUMERIC(10,2), energy_points NUMERIC(10,2), coupon_gift VARCHAR(60), water_gift VARCHAR(60), supplier_refund NUMERIC(10,2), note TEXT, updated_by VARCHAR(80), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, name VARCHAR(120), level VARCHAR(10), region VARCHAR(60), phone VARCHAR(20), kp VARCHAR(60), wecom BOOLEAN DEFAULT false, identity VARCHAR(60), welfare BOOLEAN DEFAULT false, activated_at VARCHAR(20), blacklist BOOLEAN DEFAULT false, quality BOOLEAN DEFAULT false, tags TEXT DEFAULT '[]', spend_90d NUMERIC(12,2) DEFAULT 0, orders_90d INT DEFAULT 0, after_sales_90d INT DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id BIGSERIAL PRIMARY KEY, path VARCHAR(300) UNIQUE, code VARCHAR(40), hot BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS shelves (id BIGSERIAL PRIMARY KEY, customer_id INT, code VARCHAR(60), shelf_id VARCHAR(60), name VARCHAR(120), grade VARCHAR(4), level VARCHAR(10), status VARCHAR(20), online BOOLEAN, swap BOOLEAN DEFAULT false, swap_no VARCHAR(60), owner_name VARCHAR(60), owner_phone VARCHAR(20), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id BIGSERIAL PRIMARY KEY, customer_id INT, code VARCHAR(60), point_id VARCHAR(60), point_name VARCHAR(120), online BOOLEAN, offline_7d INT DEFAULT 0, offline_30d INT DEFAULT 0, avg_offline_min INT DEFAULT 0, repair_no VARCHAR(60), withdraw BOOLEAN DEFAULT false, returned BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS contracts (id BIGSERIAL PRIMARY KEY, customer_id INT, name VARCHAR(200), contract_no VARCHAR(60), seal_status VARCHAR(20), party VARCHAR(200), sign_type VARCHAR(60), sealed_at VARCHAR(30), term_end VARCHAR(20), days_left INT, points INT, is_current BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS settlements (id BIGSERIAL PRIMARY KEY, customer_id INT, point_id VARCHAR(60), code VARCHAR(60), point_name VARCHAR(120), supplier_code VARCHAR(60), amount NUMERIC(12,2), oldest_period VARCHAR(20), status VARCHAR(20), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS trades (id BIGSERIAL PRIMARY KEY, customer_id INT, order_no VARCHAR(60), trade_no VARCHAR(60), merchant_no VARCHAR(80), code VARCHAR(60), shelf_id VARCHAR(60), phone VARCHAR(20), amount NUMERIC(10,2), status VARCHAR(20), source VARCHAR(60), pay_type VARCHAR(20), refunds INT DEFAULT 0, open_time VARCHAR(30), created_time VARCHAR(30), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS replenishments (id BIGSERIAL PRIMARY KEY, customer_id INT, code VARCHAR(60), point_name VARCHAR(120), replenish_no VARCHAR(60), on_shelf_time VARCHAR(30), amount NUMERIC(10,2), sku_count INT, status VARCHAR(20), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS wishes (id BIGSERIAL PRIMARY KEY, customer_id INT, code VARCHAR(60), product VARCHAR(120), brand VARCHAR(60), fe_code VARCHAR(40), in_list BOOLEAN DEFAULT true, supply_status VARCHAR(30), report_count INT DEFAULT 0, reporter VARCHAR(60), reporter_phone VARCHAR(20), wish_type VARCHAR(20), qty INT, period INT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS supervisions (id BIGSERIAL PRIMARY KEY, ticket_no VARCHAR(60), customer_id INT, customer_name VARCHAR(120), reason TEXT, dept VARCHAR(60), status VARCHAR(20) DEFAULT '待跟进', next_check VARCHAR(30), ops_log TEXT, created_at TIMESTAMPTZ DEFAULT now());

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['users','seed_meta','tickets','ticket_events','closures','customers','categories','shelves','devices','contracts','settlements','trades','replenishments','wishes','supervisions']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND policyname = 'wb_all_' || t) THEN
      EXECUTE format('CREATE POLICY wb_all_%I ON %I FOR ALL USING (true) WITH CHECK (true)', t, t);
    END IF;
  END LOOP;
END $$;

